                              whileTap={{ scale: 0.9 }}
                              onClick={() => updateCartQuantity(item.product.id, item.quantity + 1)}
                              className="p-1 text-gray-600 hover:text-red-500 transition-colors"
                            >
                              <Plus className="h-4 w-4" />
